<?php
require 'includes/bootstrap.php'; require_admin(); require 'includes/layout.php';
require 'includes/account_controls.php';require 'includes/partner_registration.php';
$view=$_GET['view']??'drivers';
if(in_array($view,['banners','offers'],true))redirect('content.php?type='.$view);
if(!in_array($view,['drivers','guides','packages','content'],true))$view='drivers';
$map=['drivers'=>['driver_services','service_json'],'guides'=>['guide_services','service_json'],'packages'=>['travel_packages','package_json']];
function publication_error(string $view,array $payload,array $row=[]):?string{
 if(in_array($view,['drivers','guides'],true)&&!empty($row['owner_user_id'])){
  if(!partner_service_authorized((string)$row['owner_user_id'],$payload,$view==='drivers'?'driver':'guide'))return 'El perfil o el vehículo asignado no están autorizados.';if(!account_enabled((string)$row['owner_user_id']))return 'La cuenta del colaborador está restringida.';
  $s=db()->prepare("SELECT status FROM partner_profiles WHERE user_id=?");$s->execute([$row['owner_user_id']]);
  if($s->fetchColumn()!=='approved')return 'Aprueba el registro profesional antes de publicar sus servicios.';
 }
 if(($payload['demo']??false)===true)return 'Demo records cannot be published as commercial inventory.';
 if(!is_array($payload['title']??null)||trim((string)($payload['title']['es']??''))==='')return 'A Spanish title is required before publication.';
 if($view==='drivers'){
  if(!in_array($row['city']??'', ['madrid','barcelona','malaga'],true))return 'Driver city must use a supported catalog code.';
  if(!in_array($row['category']??'', ['executive','van','standard'],true))return 'Driver category must use a supported catalog code.';
  if(empty($payload['packages'])||!is_array($payload['packages']))return 'At least one driver package is required.';
 }
 if($view==='guides'&&!in_array($row['city']??'', ['madrid','barcelona','malaga'],true))return 'Guide city must use a supported catalog code.';
 if($view==='packages'){
  if(empty($payload['destinations'])||!is_array($payload['destinations']))return 'Ordered destinations are required.';
  if(empty($payload['itinerary'])||!is_array($payload['itinerary']))return 'Itinerary content is required.';
  if(empty($payload['image'])||!is_array($payload['image'])||empty($payload['image']['url']))return 'A package image URL is required.';
 }
 return null;
}
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();
 if($view==='content'&&($_POST['action']??'')==='create_document'){
  require_owner();$slug=trim((string)($_POST['slug']??''));$version=trim((string)($_POST['version']??''));$title=isset($_POST['title_es'])?['es'=>(string)$_POST['title_es'],'en'=>(string)($_POST['title_en']??''),'ar'=>(string)($_POST['title_ar']??'')]:json_decode((string)($_POST['title_json']??''),true);$body=isset($_POST['body_es'])?['es'=>(string)$_POST['body_es'],'en'=>(string)($_POST['body_en']??''),'ar'=>(string)($_POST['body_ar']??'')]:json_decode((string)($_POST['body_json']??''),true);
  if(!preg_match('/^[a-z0-9-]{1,100}$/',$slug)||$version===''||strlen($version)>40||!is_array($title)||!is_array($body)||empty($title['es'])||empty($body['es'])){flash('error','Completa el código, la versión y los textos legales aprobados.');redirect('catalog.php?view=content');}
  try{db()->beginTransaction();db()->prepare('INSERT INTO content_documents(slug,version,title_json,body_json,active) VALUES(?,?,?,?,?)')->execute([$slug,$version,json_encode($title,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),json_encode($body,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),(int)isset($_POST['publish'])]);db()->prepare("INSERT INTO audit_log(admin_id,action,entity_type,entity_id,details_json) VALUES(?,'content_document.created','content_document',?,?)")->execute([admin()['id'],$slug,json_encode(['version'=>$version,'active'=>isset($_POST['publish'])])]);db()->commit();flash('success','Documento creado.');}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();flash('error','No se pudo crear. Comprueba si el código ya existe.');}redirect('catalog.php?view=content');
 }
 if($view==='content'&&array_key_exists('active',$_POST)){require_owner();db()->prepare('UPDATE content_documents SET active=? WHERE slug=?')->execute([(int)($_POST['active']==='1'),(string)($_POST['slug']??'')]);}
 if($view==='content'){$slug=(string)($_POST['slug']??'');$version=trim((string)($_POST['version']??''));$title=isset($_POST['title_es'])?['es'=>(string)$_POST['title_es'],'en'=>(string)($_POST['title_en']??''),'ar'=>(string)($_POST['title_ar']??'')]:json_decode((string)($_POST['title_json']??''),true);$body=isset($_POST['body_es'])?['es'=>(string)$_POST['body_es'],'en'=>(string)($_POST['body_en']??''),'ar'=>(string)($_POST['body_ar']??'')]:json_decode((string)($_POST['body_json']??''),true);if($slug&&$version&&is_array($title)&&is_array($body)){db()->prepare('UPDATE content_documents SET version=?,title_json=?,body_json=? WHERE slug=?')->execute([$version,json_encode($title,JSON_UNESCAPED_UNICODE),json_encode($body,JSON_UNESCAPED_UNICODE),$slug]);flash('success','Content updated.');}else flash('error','Title and body must be valid JSON.');}
 else{[$table,$field]=$map[$view];$action=$_POST['action']??'status';$id=(string)($_POST['id']??'');$status=(string)($_POST['status']??'');$allowed=$view==='packages'?['draft','published','paused','archived']:['draft','review','published','paused','rejected'];if($action==='create'){$payload=json_decode((string)($_POST['payload']??''),true);if(!is_array($payload))flash('error','Payload must be valid JSON.');else{$id=new_uuid();if($view==='packages')db()->prepare("INSERT INTO travel_packages(id,status,package_json) VALUES(?,'draft',?)")->execute([$id,json_encode(['id'=>$id,...$payload],JSON_UNESCAPED_UNICODE)]);elseif($view==='drivers')db()->prepare("INSERT INTO driver_services(id,status,city,category,title_json,service_json) VALUES(?,'draft',?,?,?,?)")->execute([$id,trim($_POST['city']??''),trim($_POST['category']??''),json_encode($payload['title']??[],JSON_UNESCAPED_UNICODE),json_encode(['id'=>$id,...$payload],JSON_UNESCAPED_UNICODE)]);else db()->prepare("INSERT INTO guide_services(id,status,city,title_json,service_json) VALUES(?,'draft',?,?,?)")->execute([$id,trim($_POST['city']??''),json_encode($payload['title']??[],JSON_UNESCAPED_UNICODE),json_encode(['id'=>$id,...$payload],JSON_UNESCAPED_UNICODE)]);flash('success','Draft catalog record created.');}}elseif($id&&in_array($status,$allowed,true)){$rowStmt=db()->prepare("SELECT *,$field payload FROM $table WHERE id=?");$rowStmt->execute([$id]);$record=$rowStmt->fetch();$payload=$record?json_decode($record['payload'],true):null;if(!$record||!is_array($payload))flash('error','Catalog record not found or invalid.');elseif($status==='published'&&($error=publication_error($view,$payload,$record)))flash('error',$error);else{db()->beginTransaction();db()->prepare("UPDATE $table SET status=? WHERE id=?")->execute([$status,$id]);db()->prepare("INSERT INTO audit_log(admin_id,action,entity_type,entity_id,details_json) VALUES(?,'catalog.status_changed',?,?,?)")->execute([admin()['id'],$view,$id,json_encode(['status'=>$status])]);db()->commit();flash('success','Publication status updated.');}}}
 redirect('catalog.php?view='.$view);
}
if($view==='content')$rows=db()->query('SELECT * FROM content_documents ORDER BY slug')->fetchAll();else{[$table,$field]=$map[$view];$rows=db()->query("SELECT id,status,$field payload,updated_at FROM $table ORDER BY updated_at DESC")->fetchAll();}
page_header('Mobile catalog'); ?>
<?php if($view!=='content'):?><section class="panel reservation-form"><div class="panel-head"><div><p class="eyebrow">NEW DRAFT</p><h3>Create catalog record</h3></div></div><form method="post" class="editor-form"><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="create"><?php if($view!=='packages'):?><label>City<input name="city" required></label><?php endif;?><?php if($view==='drivers'):?><label>Category<input name="category" required></label><?php endif;?><label>Complete JSON payload<textarea name="payload" rows="8" required>{"title":{"es":"","en":"","ar":""},"priceMinor":0,"currency":"EUR"}</textarea></label><button class="btn primary wide">Create draft</button></form></section><?php endif;?>
<div class="filters people-tabs"><?php foreach(['drivers'=>'Driver services','guides'=>'Guide services','packages'=>'Travel packages','content'=>'Legal & app content'] as $key=>$label):?><a class="<?=$view===$key?'active':''?>" href="?view=<?=$key?>"><?=e($label)?></a><?php endforeach;?></div><section class="panel"><div class="panel-head"><div><p class="eyebrow">MOBILE DATA</p><h3><?=count($rows)?> records</h3></div></div><div class="table-wrap"><table><thead><tr><th>Record</th><th>Preview</th><th>Status / content</th><th>Updated</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><strong><?=e($view==='content'?$row['slug']:substr($row['id'],0,18))?></strong></td><td><small><?=e(mb_strimwidth($view==='content'?$row['title_json']:$row['payload'],0,120,'…'))?></small></td><td><?php if($view==='content'):?><form method="post" class="status-form"><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="slug" value="<?=e($row['slug'])?>"><input name="version" value="<?=e($row['version'])?>"><textarea name="title_json" rows="2"><?=e($row['title_json'])?></textarea><textarea name="body_json" rows="3"><?=e($row['body_json'])?></textarea><?php if((admin()['role']??'')==='admin'):?><input type="hidden" name="active" value="0"><label><input type="checkbox" name="active" value="1" <?=$row['active']?'checked':''?>> Publicado</label><?php endif;?><button class="btn secondary">Save</button></form><?php else:?><form method="post" class="status-form"><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=e($row['id'])?>"><select name="status" onchange="this.form.submit()"><?php $states=$view==='packages'?['draft','published','paused','archived']:['draft','review','published','paused','rejected'];foreach($states as $s):?><option value="<?=$s?>" <?=$row['status']===$s?'selected':''?>><?=ucfirst($s)?></option><?php endforeach;?></select></form><?php endif;?></td><td><?=e($row['updated_at'])?><?php if((admin()['role']??'')==='admin'):?><br><a href="deletions.php?type=<?=e($view==='content'?'documents':$view)?>&amp;id=<?=e(rawurlencode($view==='content'?$row['slug']:$row['id']))?>">Eliminar…</a><?php endif;?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="4" class="empty">No records yet.</td></tr><?php endif;?></tbody></table></div></section>
<?php if($view==='content'&&(admin()['role']??'')==='admin'):?><section class="panel"><h3>Añadir documento legal</h3><p>Para colaboradores: collaboration-terms, privacy y partner-economic-terms. Introduce únicamente textos revisados y aprobados por la agencia.</p><form method="post" class="editor-form"><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="create_document"><label>Código<input name="slug" pattern="[a-z0-9-]{1,100}" required></label><label>Versión<input name="version" maxlength="40" required></label><?php foreach(['es'=>'Español','en'=>'English','ar'=>'العربية'] as $locale=>$language):?><fieldset><legend><?=e($language)?></legend><label>Título<input name="title_<?=$locale?>" maxlength="200" <?=$locale==='es'?'required':''?> dir="<?=$locale==='ar'?'rtl':'ltr'?>"></label><label>Contenido<textarea name="body_<?=$locale?>" rows="8" <?=$locale==='es'?'required':''?> dir="<?=$locale==='ar'?'rtl':'ltr'?>"></textarea></label></fieldset><?php endforeach;?><label><input type="checkbox" name="publish"> Publicar texto revisado</label><button class="btn primary">Crear documento</button></form></section><?php endif;page_footer();
